.lc text{font-family:"Noto Sans KR","Noto Sans CJK KR","Apple SD Gothic Neo","Malgun Gothic",sans-serif}
.lc .seg{fill:none;stroke-width:5;stroke-linecap:round;stroke-dasharray:1;stroke-dashoffset:0}
.lc.wait *{animation-play-state:paused!important}
.lc.play .seg{animation:lcDraw .7s ease-out var(--d) both}
.lc .fade{opacity:1}
.lc.play .fade{animation:lcIn .5s ease var(--d) both}
.lc .fork{opacity:0}
.lc.play .fork{animation:lcFork 1s ease var(--d) both}
.lc .area{opacity:.9}
.lc.play .area{animation:lcIn 1s ease var(--d) both}
.lc .glow{opacity:.35;transform-origin:center;transform-box:fill-box}
.lc.play .glow{animation:lcIn .6s ease var(--d) both,lcPulse 1.6s ease-in-out calc(var(--d) + .6s) 2}
@keyframes lcDraw{from{stroke-dashoffset:1}to{stroke-dashoffset:0}}
@keyframes lcIn{from{opacity:0}to{opacity:var(--o,1)}}
@keyframes lcFork{0%{opacity:0}30%{opacity:1}75%{opacity:1}100%{opacity:0}}
@keyframes lcPulse{0%,100%{transform:scale(1)}50%{transform:scale(1.6)}}
.lc-steps{display:flex;flex-wrap:wrap;gap:6px;margin:12px 2px 0;padding:0;list-style:none}
.lc-steps li{font-size:13px;font-weight:700;color:#6E7892;background:#EBEDF3;border-radius:999px;padding:5px 11px;word-break:keep-all}
.lc-steps li b{color:inherit;margin-right:4px}
.lc.play .lc-steps li{animation:lcChip .4s ease var(--d) both}
@keyframes lcChip{from{background:#EBEDF3;color:#6E7892}to{background:#EEF2FD;color:#1E2A5A}}
.lc-steps li{background:#EEF2FD;color:#1E2A5A}
.lc-bar{display:flex;justify-content:flex-end;margin-top:8px}
.lc-replay{border:1.5px solid #E0E3EB;background:#FFFFFF;border-radius:999px;padding:5px 14px;font-size:13px;font-weight:800;color:#192450;cursor:pointer}
.lc-replay:hover{border-color:#192450}
@media (prefers-reduced-motion:reduce){.lc:not(.force) *{animation:none!important}}
