<script>
/* 3S cards: highlight S1 → S2 → S3 in turn while visible; hover/focus picks one; reduced motion = no auto cycle */
(function(){
  var box=document.querySelector('.fz-steps'); if(!box) return;
  var cards=[].slice.call(box.querySelectorAll('.fz-step')); if(!cards.length) return;
  var i=0, timer=null, hold=false, still=window.matchMedia&&window.matchMedia('(prefers-reduced-motion: reduce)').matches;
  function show(k){cards.forEach(function(c,j){c.classList.toggle('on',j===k)}); i=k;}
  function tick(){ if(!hold) show((i+1)%cards.length); }
  function start(){ if(still||timer) return; show(i); timer=setInterval(tick,2600); }
  function stop(){ clearInterval(timer); timer=null; }
  cards.forEach(function(c,k){
    c.setAttribute('tabindex','0');
    c.addEventListener('mouseenter',function(){hold=true;show(k)});
    c.addEventListener('focus',function(){hold=true;show(k)});
    c.addEventListener('mouseleave',function(){hold=false});
    c.addEventListener('blur',function(){hold=false});
  });
  if(still){ show(0); return; }
  if('IntersectionObserver' in window){
    new IntersectionObserver(function(es){es.forEach(function(e){ if(e.isIntersecting){ show(0); start(); } else stop(); })},{threshold:.5}).observe(box);
  } else start();
})();
</script>

